CREATE TABLE IF NOT EXISTS organizations(id TEXT PRIMARY KEY,name TEXT NOT NULL,type TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,name TEXT NOT NULL,email TEXT NOT NULL UNIQUE,org_id TEXT NOT NULL REFERENCES organizations(id),role TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS api_keys(id TEXT PRIMARY KEY,org_id TEXT NOT NULL REFERENCES organizations(id),key_hash TEXT NOT NULL UNIQUE,capability TEXT NOT NULL,expires_at TEXT NOT NULL,created_at TEXT NOT NULL,revoked_at TEXT);
CREATE TABLE IF NOT EXISTS properties(id TEXT PRIMARY KEY,owner_org_id TEXT NOT NULL REFERENCES organizations(id),name TEXT NOT NULL,channel TEXT NOT NULL,description TEXT NOT NULL,verification TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS inventory(id TEXT PRIMARY KEY,property_id TEXT NOT NULL REFERENCES properties(id),name TEXT NOT NULL,format TEXT NOT NULL,price_minor INTEGER NOT NULL CHECK(price_minor>0),currency TEXT NOT NULL,availability TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS campaigns(id TEXT PRIMARY KEY,advertiser_org_id TEXT NOT NULL REFERENCES organizations(id),name TEXT NOT NULL,objective TEXT NOT NULL,status TEXT NOT NULL,budget_minor INTEGER NOT NULL CHECK(budget_minor>0),currency TEXT NOT NULL,destination TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS bookings(id TEXT PRIMARY KEY,campaign_id TEXT NOT NULL REFERENCES campaigns(id),inventory_id TEXT NOT NULL REFERENCES inventory(id),owner_org_id TEXT NOT NULL REFERENCES organizations(id),advertiser_org_id TEXT NOT NULL REFERENCES organizations(id),status TEXT NOT NULL,price_minor INTEGER NOT NULL,currency TEXT NOT NULL,proof_url TEXT,proof_type TEXT,created_at TEXT NOT NULL,published_at TEXT,settled_at TEXT);
CREATE INDEX IF NOT EXISTS idx_bookings_advertiser ON bookings(advertiser_org_id,status);
CREATE INDEX IF NOT EXISTS idx_bookings_owner ON bookings(owner_org_id,status);
CREATE TABLE IF NOT EXISTS tracking_links(token TEXT PRIMARY KEY,booking_id TEXT NOT NULL REFERENCES bookings(id),advertiser_org_id TEXT NOT NULL REFERENCES organizations(id),destination TEXT NOT NULL,expires_at TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS events(id TEXT PRIMARY KEY,org_id TEXT NOT NULL REFERENCES organizations(id),booking_id TEXT NOT NULL REFERENCES bookings(id),type TEXT NOT NULL,provenance TEXT NOT NULL,occurred_at TEXT NOT NULL,received_at TEXT NOT NULL,anonymous_id TEXT,subject_id TEXT,metadata TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_events_org_booking ON events(org_id,booking_id,type);
CREATE TABLE IF NOT EXISTS conversions(id TEXT PRIMARY KEY,org_id TEXT NOT NULL REFERENCES organizations(id),booking_id TEXT NOT NULL REFERENCES bookings(id),event_id TEXT NOT NULL,stage TEXT NOT NULL,value_minor INTEGER NOT NULL DEFAULT 0,currency TEXT NOT NULL,provenance TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(org_id,event_id));
CREATE TABLE IF NOT EXISTS ledger_entries(id TEXT PRIMARY KEY,batch_id TEXT NOT NULL,org_id TEXT NOT NULL REFERENCES organizations(id),account TEXT NOT NULL,amount INTEGER NOT NULL,currency TEXT NOT NULL,ref TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TRIGGER IF NOT EXISTS ledger_no_update BEFORE UPDATE ON ledger_entries BEGIN SELECT RAISE(ABORT,'ledger entries are immutable'); END;
CREATE TRIGGER IF NOT EXISTS ledger_no_delete BEFORE DELETE ON ledger_entries BEGIN SELECT RAISE(ABORT,'ledger entries are immutable'); END;
CREATE INDEX IF NOT EXISTS idx_ledger_org_account ON ledger_entries(org_id,account,currency);
CREATE UNIQUE INDEX IF NOT EXISTS idx_ledger_ref_account ON ledger_entries(org_id,ref,account);
CREATE TABLE IF NOT EXISTS audit_log(id TEXT PRIMARY KEY,actor_id TEXT NOT NULL,org_id TEXT NOT NULL,action TEXT NOT NULL,target_id TEXT NOT NULL,detail TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TRIGGER IF NOT EXISTS audit_no_update BEFORE UPDATE ON audit_log BEGIN SELECT RAISE(ABORT,'audit rows are immutable'); END;
CREATE TRIGGER IF NOT EXISTS audit_no_delete BEFORE DELETE ON audit_log BEGIN SELECT RAISE(ABORT,'audit rows are immutable'); END;
CREATE TABLE IF NOT EXISTS outbox(id TEXT PRIMARY KEY,org_id TEXT NOT NULL REFERENCES organizations(id),type TEXT NOT NULL,version INTEGER NOT NULL,payload TEXT NOT NULL,created_at TEXT NOT NULL,processed_at TEXT);
CREATE TABLE IF NOT EXISTS idempotency(org_id TEXT NOT NULL,key TEXT NOT NULL,response TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(org_id,key));
CREATE TABLE IF NOT EXISTS contact_permissions(id TEXT PRIMARY KEY,org_id TEXT NOT NULL REFERENCES organizations(id),contact_hash TEXT NOT NULL,channel TEXT NOT NULL,purpose TEXT NOT NULL,status TEXT NOT NULL,proof_source TEXT NOT NULL,proof_text TEXT NOT NULL,captured_at TEXT NOT NULL,withdrawn_at TEXT,UNIQUE(org_id,contact_hash,channel,purpose));
CREATE TABLE IF NOT EXISTS permission_history(id TEXT PRIMARY KEY,permission_id TEXT NOT NULL REFERENCES contact_permissions(id),org_id TEXT NOT NULL REFERENCES organizations(id),action TEXT NOT NULL,proof_source TEXT NOT NULL,proof_text TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TRIGGER IF NOT EXISTS permission_history_no_update BEFORE UPDATE ON permission_history BEGIN SELECT RAISE(ABORT,'permission history is immutable'); END;
CREATE TRIGGER IF NOT EXISTS permission_history_no_delete BEFORE DELETE ON permission_history BEGIN SELECT RAISE(ABORT,'permission history is immutable'); END;
CREATE INDEX IF NOT EXISTS idx_permissions_org_status ON contact_permissions(org_id,status,channel);
CREATE TABLE IF NOT EXISTS messages(id TEXT PRIMARY KEY,org_id TEXT NOT NULL REFERENCES organizations(id),contact_hash TEXT NOT NULL,channel TEXT NOT NULL,purpose TEXT NOT NULL,content_hash TEXT NOT NULL,idempotency_key TEXT NOT NULL,status TEXT NOT NULL,provider_message_id TEXT NOT NULL,estimate_minor INTEGER NOT NULL,currency TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(org_id,idempotency_key));
CREATE INDEX IF NOT EXISTS idx_messages_org_status ON messages(org_id,status,created_at);
